import type { ComponentType, LazyExoticComponent } from "react"
import type { Tool } from "ai"
import type { z } from "zod"

export class ToolPayloadError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "ToolPayloadError"
  }
}

export type ToolRenderHandlers = {
  onSuggestedAction?: (action: { label: string; prompt: string; description?: string }) => void
  onConfirm?: (confirmation: { id: string; label: string }) => void
  onCancel?: (confirmation: { id: string; label: string }) => void
  onFormSubmit?: (values: Record<string, string | number | boolean>) => void
  onRowAction?: (action: { id: string; rowId: string }) => void
}

export type ToolPartLike = {
  type: string
  toolName?: string
  toolCallId?: string
  state?: string
  input?: unknown
  output?: unknown
  errorText?: string
  toolMetadata?: {
    fableState?: "loading" | "empty" | "error" | "disabled"
  }
}

export type FableRenderableComponent<TProps extends object> =
  | ComponentType<TProps>
  | LazyExoticComponent<ComponentType<TProps>>

export interface FableComponent<TSchema extends z.ZodType = z.ZodType, TProps extends object = Record<string, unknown>> {
  name: string
  schema: TSchema
  tool: Tool
  renderer: {
    Component: FableRenderableComponent<TProps>
    loadingProps: TProps
    emptyProps: TProps
    errorProps: (description: string) => TProps
    toProps: (data: z.infer<TSchema>, handlers: ToolRenderHandlers) => TProps
  }
}

export type FableToolRegistry = Record<string, FableComponent<z.ZodType, any>>

export function defineFableComponent<TSchema extends z.ZodType, TProps extends object>(
  def: FableComponent<TSchema, TProps>,
) {
  return def
}

export function getToolNameFromPart(part: ToolPartLike) {
  if (part.toolName) {
    return part.toolName
  }

  if (part.type.startsWith("tool-")) {
    return part.type.slice("tool-".length)
  }

  return null
}

import * as React from "react"
import type { ReactNode } from "react"

import {
  getToolNameFromPart,
  ToolPayloadError,
  type FableToolRegistry,
  type ToolPartLike,
  type ToolRenderHandlers,
} from "./definitions"

function UnknownToolPart({ name }: { name: string }) {
  return (
    <div className="rounded-md border bg-muted/40 p-4 text-sm text-muted-foreground">
      Unknown Fable tool part: <code>{name}</code>
    </div>
  )
}

function renderComponent(
  Component: FableToolRegistry[string]["renderer"]["Component"],
  props: Record<string, unknown>,
) {
  return (
    <React.Suspense fallback={null}>
      <Component {...props} />
    </React.Suspense>
  )
}

export function renderFableToolPart({
  part,
  registry,
  handlers = {},
}: {
  part: ToolPartLike
  registry: FableToolRegistry
  handlers?: ToolRenderHandlers
}): ReactNode {
  const toolName = getToolNameFromPart(part)
  const def = toolName ? registry[toolName] : undefined

  if (!def) {
    return <UnknownToolPart name={toolName ?? part.type} />
  }

  const fableState = part.toolMetadata?.fableState
  const isDisabled = fableState === "disabled"

  if (part.state === "input-streaming" || fableState === "loading") {
    return renderComponent(def.renderer.Component, def.renderer.loadingProps)
  }

  if (part.state === "output-error" || fableState === "error") {
    return renderComponent(
      def.renderer.Component,
      def.renderer.errorProps(part.errorText || "The tool result could not be rendered."),
    )
  }

  if (fableState === "empty") {
    return renderComponent(def.renderer.Component, def.renderer.emptyProps)
  }

  const parsed = def.schema.safeParse(part.output ?? part.input)

  if (!parsed.success) {
    return renderComponent(
      def.renderer.Component,
      def.renderer.errorProps("The tool result did not match the expected data contract."),
    )
  }

  try {
    return renderComponent(
      def.renderer.Component,
      {
        ...def.renderer.toProps(parsed.data, handlers),
        isDisabled,
      },
    )
  } catch (error) {
    const description =
      error instanceof ToolPayloadError ? error.message : "Unexpected error rendering component."

    return renderComponent(def.renderer.Component, def.renderer.errorProps(description))
  }
}

export function FableToolPart({
  part,
  registry,
  handlers,
}: {
  part: ToolPartLike
  registry: FableToolRegistry
  handlers?: ToolRenderHandlers
}) {
  return <>{renderFableToolPart({ part, registry, handlers })}</>
}

import type { DataColumn, DataRow } from "./types"

export function getDataValue(row: DataRow, key: string): unknown {
  const cells = row.cells

  if (cells && typeof cells === "object" && key in cells) {
    return (cells as Record<string, unknown>)[key]
  }

  return key.split(".").reduce<unknown>((value, part) => {
    if (value && typeof value === "object" && part in value) {
      return (value as Record<string, unknown>)[part]
    }

    return undefined
  }, row)
}

export function normalizeDataValue(value: unknown) {
  if (value instanceof Date) {
    return value.toISOString()
  }

  if (value == null) {
    return ""
  }

  return String(value)
}

export function formatDataCell(row: DataRow, column: DataColumn) {
  const value = getDataValue(row, column.key)

  if (value == null) {
    return ""
  }

  if (column.type === "date" || column.type === "datetime") {
    const date = value instanceof Date ? value : new Date(String(value))

    if (!Number.isNaN(date.getTime())) {
      return column.type === "date" ? date.toLocaleDateString() : date.toLocaleString()
    }
  }

  return normalizeDataValue(value)
}

export function getRowId(row: DataRow) {
  const id = row.id ?? row._id ?? row.uid ?? row.orderId ?? row.order
  return id == null ? null : String(id)
}

import { getDataValue, normalizeDataValue } from "./format"
import type { DataColumn, DataQuery, DataQueryResult, DataRow } from "./types"

function matchesSearch(row: DataRow, query: string, columns?: DataColumn[]) {
  const keys = columns?.map((column) => column.key) ?? Object.keys(row)
  const normalizedQuery = query.trim().toLowerCase()

  if (!normalizedQuery) {
    return true
  }

  return keys.some((key) => normalizeDataValue(getDataValue(row, key)).toLowerCase().includes(normalizedQuery))
}

function matchesFilters(row: DataRow, filters: Record<string, unknown>) {
  return Object.entries(filters).every(([key, expected]) => {
    if (expected == null || expected === "" || (Array.isArray(expected) && expected.length === 0)) {
      return true
    }

    const value = getDataValue(row, key)

    if (Array.isArray(expected)) {
      return expected.map(String).includes(String(value))
    }

    if (typeof expected === "boolean") {
      return Boolean(value) === expected
    }

    return String(value).toLowerCase() === String(expected).toLowerCase()
  })
}

function compareValues(a: unknown, b: unknown) {
  if (typeof a === "number" && typeof b === "number") {
    return a - b
  }

  return normalizeDataValue(a).localeCompare(normalizeDataValue(b), undefined, {
    numeric: true,
    sensitivity: "base",
  })
}

export function queryLocalRows<Row extends DataRow>(
  rows: Row[],
  query: DataQuery = {},
  columns?: DataColumn[],
): DataQueryResult<Row> {
  const page = query.page ?? 1
  const pageSize = query.pageSize ?? (rows.length || 10)

  let nextRows = rows.filter((row) => matchesSearch(row, query.search ?? "", columns))
  nextRows = nextRows.filter((row) => matchesFilters(row, query.filters ?? {}))

  if (query.sort?.key) {
    const { key, direction } = query.sort
    nextRows = [...nextRows].sort((a, b) => {
      const result = compareValues(getDataValue(a, key), getDataValue(b, key))
      return direction === "desc" ? -result : result
    })
  }

  const totalRows = nextRows.length
  const start = (page - 1) * pageSize
  const pagedRows = nextRows.slice(start, start + pageSize)

  return {
    rows: pagedRows,
    totalRows,
    page,
    pageSize,
    nextCursor: start + pageSize < totalRows ? String(page + 1) : undefined,
    previousCursor: page > 1 ? String(page - 1) : undefined,
  }
}

import type {
  AgentResourceManifest,
  DataActionInput,
  DataActionResult,
  DataQuery,
  DataQueryResult,
  DataRow,
  DataSourceContext,
  DataSourceDriver,
  ResourceConfig,
  ResourceRuntime,
} from "./types"

function warnOnce(message: string) {
  if (process.env.NODE_ENV === "development") {
    console.warn(message)
  }
}

export function defineResource<TSource, Row extends DataRow = DataRow>(
  resource: ResourceConfig<TSource, Row>,
) {
  return resource
}

export function defineResourceRuntime<Row extends DataRow = DataRow>(runtime: ResourceRuntime<Row>) {
  return runtime
}

export class DataSourceRegistry {
  private drivers = new Map<string, DataSourceDriver<any, any>>()
  private resources = new Map<string, ResourceConfig<any, any>>()
  private runtimes = new Map<string, ResourceRuntime<any>>()

  registerDriver(id: string, driver: DataSourceDriver<any, any>) {
    const existing = this.drivers.get(id)

    if (existing) {
      if (existing !== driver) {
        warnOnce(`[fable-ui] Driver "${id}" is already registered. Keeping the latest registration.`)
      }
    }

    this.drivers.set(id, driver)
    return this
  }

  registerResource<TSource, Row extends DataRow = DataRow>(resource: ResourceConfig<TSource, Row>) {
    const existing = this.resources.get(resource.id)

    if (existing) {
      if (JSON.stringify(existing) !== JSON.stringify(resource)) {
        warnOnce(`[fable-ui] Resource "${resource.id}" is already registered. Keeping the latest registration.`)
      }
    }

    this.resources.set(resource.id, resource)
    return this
  }

  registerResourceRuntime<Row extends DataRow = DataRow>(resourceId: string, runtime: ResourceRuntime<Row>) {
    const existing = this.runtimes.get(resourceId)

    if (existing && existing !== runtime) {
      warnOnce(`[fable-ui] Runtime for resource "${resourceId}" is already registered. Keeping the latest registration.`)
    }

    this.runtimes.set(resourceId, runtime)
    return this
  }

  getResource(resourceId: string) {
    return this.resources.get(resourceId)
  }

  listResources() {
    return Array.from(this.resources.values())
  }

  resolve(resourceId: string) {
    const resource = this.resources.get(resourceId)

    if (!resource) {
      throw new Error(`Fable resource "${resourceId}" is not registered.`)
    }

    const driver = this.drivers.get(resource.driver)

    if (!driver) {
      throw new Error(`Fable driver "${resource.driver}" for resource "${resourceId}" is not registered.`)
    }

    return {
      resource,
      driver,
      runtime: this.runtimes.get(resourceId),
    }
  }

  async list<Row extends DataRow = DataRow>(
    resourceId: string,
    query: DataQuery = {},
    ctx: DataSourceContext = {},
  ): Promise<DataQueryResult<Row>> {
    const { resource, driver, runtime } = this.resolve(resourceId)

    if (runtime?.list) {
      return runtime.list(resource, query, ctx) as Promise<DataQueryResult<Row>> | DataQueryResult<Row>
    }

    return driver.list(resource, query, ctx, runtime)
  }

  async get<Row extends DataRow = DataRow>(
    resourceId: string,
    rowId: string,
    ctx: DataSourceContext = {},
  ): Promise<Row | null> {
    const { resource, driver, runtime } = this.resolve(resourceId)

    if (runtime?.get) {
      return runtime.get(resource, rowId, ctx) as Promise<Row | null> | Row | null
    }

    return driver.get ? driver.get(resource, rowId, ctx, runtime) : null
  }

  async executeAction(
    input: DataActionInput,
    ctx: DataSourceContext = {},
  ): Promise<DataActionResult> {
    const { resource, driver, runtime } = this.resolve(input.resourceId)

    if (runtime?.executeAction) {
      return runtime.executeAction(input, resource, ctx)
    }

    if (!driver.executeAction) {
      throw new Error(`Fable resource "${input.resourceId}" does not support actions.`)
    }

    return driver.executeAction(input, resource, ctx, runtime)
  }

  getAgentResourceManifest(): AgentResourceManifest {
    return {
      resources: this.listResources().map((resource) => ({
        id: resource.id,
        label: resource.label,
        entityLabel: resource.entityLabel,
        description: resource.agent?.description,
        aliases: resource.agent?.aliases,
        useWhen: resource.agent?.useWhen,
        avoidWhen: resource.agent?.avoidWhen,
        columns: resource.columns.map(({ key, label, type, description }) => ({
          key,
          label,
          type,
          description,
        })),
        filters: resource.filters?.map(({ key, label, type, options }) => ({
          key,
          label,
          type,
          options,
        })),
        sort: resource.sort,
        actions: resource.actions?.map(({ id, label, description, variant, requiresConfirmation, fields }) => ({
          id,
          label,
          description,
          variant,
          requiresConfirmation,
          fields,
        })),
      })),
    }
  }
}

export const fableRegistry = new DataSourceRegistry()

"use client"

import * as React from "react"

import { fableRegistry, type DataSourceRegistry } from "./registry"
import type { DataActionInput, DataQuery, DataSourceContext } from "./types"

type FableDataContextValue = {
  registry: DataSourceRegistry
  context: DataSourceContext
}

const FableDataContext = React.createContext<FableDataContextValue | null>(null)

export function FableDataProvider({
  registry = fableRegistry,
  context = {},
  children,
}: {
  registry?: DataSourceRegistry
  context?: DataSourceContext
  children: React.ReactNode
}) {
  const value = React.useMemo(() => ({ registry, context }), [context, registry])

  return <FableDataContext.Provider value={value}>{children}</FableDataContext.Provider>
}

export function useFableDataContext() {
  const value = React.useContext(FableDataContext)

  if (!value) {
    throw new Error("useFableDataContext must be used within FableDataProvider.")
  }

  return value
}

export function useOptionalFableDataContext() {
  return React.useContext(FableDataContext)
}

export function useFableResource(resourceId: string) {
  const { registry, context } = useFableDataContext()
  const resource = registry.getResource(resourceId)

  const list = React.useCallback(
    (query: DataQuery = {}) => registry.list(resourceId, query, context),
    [context, registry, resourceId],
  )

  const runAction = React.useCallback(
    (input: Omit<DataActionInput, "resourceId">) =>
      registry.executeAction({ ...input, resourceId }, context),
    [context, registry, resourceId],
  )

  return {
    resource,
    list,
    runAction,
  }
}
